mapper.select:
select id, dict_code, dict_label, dict_value, tag_type, parent_id, sort, status, remark, if(parent_id = 0, '顶级', (select bdp.dict_label from bedrock_dict bdp where bdp.id = bedrock_dict.parent_id)) as parentName, (exists(select 1 from bedrock_dict bdh where bdh.parent_id = bedrock_dict.id and bdh.is_deleted = 0)) as hasChildren from bedrock_dict where is_deleted = 0 and parent_id = #{dict.parentId}
and dict_code = #{dict.dictCode}
and dict_label like concat('%',#{dict.dictLabel},'%')
and status = #{dict.status}
order by sort, create_time desc
